function auditAdmin(user,action,targetType='',targetId='',details={}){if(user?.role!=='admin')return;try{db.prepare('INSERT INTO admin_audit_log(admin_user_id,action,target_type,target_id,details) VALUES(?,?,?,?,?)').run(user.id,clean(action,80),clean(targetType,50),clean(String(targetId||''),80),JSON.stringify(details||{}).slice(0,4000))}catch(e){console.warn('[audit]',e.message)}}
function parseJSONSafe(v,fallback={}){try{const x=JSON.parse(v||'');return x??fallback}catch{return fallback}}
function timeFromText(v){const m=String(v||'').match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/);return m?`${String(m[1]).padStart(2,'0')}:${m[2]}`:''}
function tripTimeline(tripId,ownerId){
 const itin=db.prepare('SELECT id,item_date,item_time,timezone,title,location,notes FROM itinerary_items WHERE trip_id=? AND user_id=? ORDER BY item_date,item_time,id').all(tripId,ownerId);
 const res=db.prepare('SELECT id,kind,provider,confirmation,status,created_at,event_date,event_time,timezone FROM reservations WHERE trip_id=? AND user_id=? ORDER BY id').all(tripId,ownerId);
 const out=itin.map(x=>({source:'itinerary',id:x.id,date:x.item_date||'',time:x.item_time||timeFromText(`${x.title} ${x.notes}`),timezone:x.timezone||'',title:x.title,place:x.location||'',detail:x.notes||'',kind:'Roteiro'}));
 for(const r of res){const blob=`${r.provider} ${r.confirmation}`;const dm=blob.match(/\b(20\d{2}-\d{2}-\d{2}|\d{2}\/\d{2}\/20\d{2})\b/);let date='';if(dm){date=dm[1].includes('/')?dm[1].split('/').reverse().join('-'):dm[1]}out.push({source:'reservation',id:r.id,date:r.event_date||date,time:r.event_time||timeFromText(blob),timezone:r.timezone||'',title:`${r.kind}: ${r.provider||'Reserva'}`,place:r.provider||'',detail:r.confirmation||'',kind:r.kind,status:r.status});}
 return out.sort((a,b)=>`${a.date||'9999'} ${a.time||'99:99'}`.localeCompare(`${b.date||'9999'} ${b.time||'99:99'}`));
}
function preparationForTrip(t,ownerId){const counts={itinerary:db.prepare('SELECT COUNT(*) n FROM itinerary_items WHERE trip_id=? AND user_id=?').get(t.id,ownerId).n,reservations:db.prepare('SELECT COUNT(*) n FROM reservations WHERE trip_id=? AND user_id=?').get(t.id,ownerId).n,checklist:db.prepare('SELECT COUNT(*) n,SUM(CASE WHEN done=1 THEN 1 ELSE 0 END) done FROM checklist_items WHERE trip_id=? AND user_id=?').get(t.id,ownerId),documents:db.prepare("SELECT COUNT(*) n FROM trip_tools WHERE trip_id=? AND user_id=? AND type='document'").get(t.id,ownerId).n};const bought=db.prepare('SELECT COALESCE(SUM(amount),0) n FROM purchases WHERE trip_id=? AND user_id=? AND currency=?').get(t.id,ownerId,t.currency).n;const checks=[!!t.start_date&&!!t.end_date,counts.itinerary>0,counts.reservations>0,counts.checklist.n>0&&Number(counts.checklist.done||0)>=Number(counts.checklist.n||0)*.6,counts.documents>0,Number(t.target_amount||0)<=0||Number(bought)>=Number(t.target_amount||0)];return {score:Math.round(checks.filter(Boolean).length/checks.length*100),counts,bought:Number(bought),target:Number(t.target_amount||0),items:[{label:'Datas da viagem',done:checks[0]},{label:'Roteiro cadastrado',done:checks[1]},{label:'Reservas cadastradas',done:checks[2]},{label:'Checklist avançado',done:checks[3]},{label:'Documentos essenciais',done:checks[4]},{label:'Meta cambial',done:checks[5]}]}}
async function timelineConflicts(timeline){const out=[];for(let i=1;i<timeline.length;i++){const a=timeline[i-1],b=timeline[i];if(a.date&&a.date===b.date&&a.time&&b.time){const [ah,am]=a.time.split(':').map(Number),[bh,bm]=b.time.split(':').map(Number),gap=(bh*60+bm)-(ah*60+am);if(gap>=0&&gap<30)out.push({severity:'warning',message:`Pouco intervalo (${gap} min) entre “${a.title}” e “${b.title}”.`,date:a.date})}}return out}
async function computeRoutes(points,mode='TRANSIT'){const key=process.env.GOOGLE_ROUTES_API_KEY;if(!key||points.length<2)throw new Error('Routes indisponível');const payload={origin:{address:points[0].address},destination:{address:points.at(-1).address},travelMode:mode,languageCode:'pt-BR',units:'METRIC'};if(points.length>2)payload.intermediates=points.slice(1,-1).map(x=>({address:x.address}));const r=await fetch('https://routes.googleapis.com/directions/v2:computeRoutes',{method:'POST',headers:{'content-type':'application/json','X-Goog-Api-Key':key,'X-Goog-FieldMask':'routes.distanceMeters,routes.duration'},body:JSON.stringify(payload),signal:AbortSignal.timeout(8000)});if(!r.ok)throw new Error('Routes '+r.status);const d=await r.json(),rt=d.routes?.[0];if(!rt)throw new Error('Rota não encontrada');return {distance_meters:Number(rt.distanceMeters||0),duration_seconds:Math.round(Number(String(rt.duration||'0s').replace('s',''))||0)}}
async function routeAwareConflicts(timeline,tripId){const out=await timelineConflicts(timeline);for(let i=1;i<timeline.length;i++){const a=timeline[i-1],b=timeline[i];if(!a.date||a.date!==b.date||!a.time||!b.time||!a.place||!b.place)continue;const gap=(Number(b.time.slice(0,2))*60+Number(b.time.slice(3)))-(Number(a.time.slice(0,2))*60+Number(a.time.slice(3)));if(gap<=0)continue;try{const r=await computeRoutes([{label:a.title,address:a.place},{label:b.title,address:b.place}],'TRANSIT');const need=Math.ceil(Number(r.duration_seconds||0)/60)+15;if(need>gap)out.push({severity:'warning',date:a.date,message:`Deslocamento apertado entre “${a.title}” e “${b.title}”: cerca de ${need-15} min de trajeto + 15 min de margem para ${gap} min disponíveis.`})}catch{}}return out}
function expenseSettlement(tripId,ownerId,ownerName){const rows=db.prepare("SELECT data FROM trip_tools WHERE trip_id=? AND user_id=? AND type='expense'").all(tripId,ownerId),balance={};for(const row of rows){const d=parseJSONSafe(row.data,{}),amount=Number(d.amount||0);if(!amount)continue;const people=[ownerName,...(Array.isArray(d.splitNames)?d.splitNames:String(d.split||'').split(',').map(x=>x.trim()).filter(Boolean))];const uniq=[...new Set(people.filter(Boolean))],share=amount/Math.max(1,uniq.length),payer=d.paidBy||ownerName;for(const n of uniq)balance[n]=(balance[n]||0)-share;balance[payer]=(balance[payer]||0)+amount}const paidRows=db.prepare('SELECT id,from_name,to_name,amount,paid_at FROM expense_settlements WHERE trip_id=? AND user_id=? AND paid_at IS NOT NULL').all(tripId,ownerId),creditors=Object.entries(balance).filter(([,v])=>v>.01).map(([n,v])=>[n,v]),debtors=Object.entries(balance).filter(([,v])=>v<-.01).map(([n,v])=>[n,-v]),transfers=[];for(const d of debtors){for(const c of creditors){const x=Math.min(d[1],c[1]);if(x>.01){const amount=Number(x.toFixed(2)),paid=paidRows.find(r=>r.from_name===d[0]&&r.to_name===c[0]&&Math.abs(Number(r.amount)-amount)<.01);transfers.push({from:d[0],to:c[0],amount,paid:!!paid,settlement_id:paid?.id||null,paid_at:paid?.paid_at||null});d[1]-=x;c[1]-=x}}}return {balance,transfers}}
function dateInZone(zone){try{return new Intl.DateTimeFormat('en-CA',{timeZone:zone||'UTC',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}catch{return new Date().toISOString().slice(0,10)}}
function clothesForWeather(w){if(!w?.days?.length)return [];let min=Math.min(...w.days.map(x=>Number(x.min)).filter(Number.isFinite)),max=Math.max(...w.days.map(x=>Number(x.max)).filter(Number.isFinite)),rain=Math.max(...w.days.map(x=>Number(x.rain_probability||0)));const a=['calçados confortáveis'];if(min<12)a.push('casaco quente','calça comprida','camadas térmicas');else if(min<19)a.push('casaco leve','calça');if(max>=26)a.push('camisetas leves','bermuda/short','protetor solar');if(rain>=40)a.push('capa de chuva ou guarda-chuva compacto');return [...new Set(a)]}
function tripWeatherCandidates(tripId,ownerId,t){const budget=db.prepare('SELECT country,city FROM budget_items WHERE trip_id=? AND user_id=? ORDER BY id').all(tripId,ownerId);const cities=[];for(const x of budget){const city=clean(x.city,80),country=clean(x.country,80);if(city)cities.push({label:city,query:[city,country].filter(Boolean).join(', '),country})}const seen=new Set(),out=[];for(const x of cities){const k=x.label.toLocaleLowerCase('pt-BR');if(!seen.has(k)){seen.add(k);out.push(x)}}const destinations=String(t.destinations||'').split(/[,;\n]+/).map(x=>clean(x,80)).filter(Boolean);for(const d of destinations){const represented=out.some(x=>x.country&&x.country.toLocaleLowerCase('pt-BR')===d.toLocaleLowerCase('pt-BR'));const k=d.toLocaleLowerCase('pt-BR');if(!represented&&!seen.has(k)){seen.add(k);out.push({label:d,query:d,country:d})}}return out.slice(0,12)}
function shiftTripDateToYear(date,year){const m=String(date||'').match(/^\d{4}-(\d{2})-(\d{2})$/);if(!m)return '';let d=`${year}-${m[1]}-${m[2]}`;if(m[1]==='02'&&m[2]==='29'&&!new Date(`${d}T12:00:00Z`).getUTCDate())d=`${year}-02-28`;return d}
async function openMeteoHistoricalTypical(place,startDate,endDate){const lat=Number(place?.location?.latitude),lon=Number(place?.location?.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon)||!startDate||!endDate)return null;const tripYear=Number(String(startDate).slice(0,4)),now=new Date(),historicalYear=Math.min(tripYear-1,now.getUTCFullYear()-1);if(historicalYear<1940)return null;const startYear=Number(String(startDate).slice(0,4)),endYear=Number(String(endDate).slice(0,4)),start=shiftTripDateToYear(startDate,historicalYear),end=shiftTripDateToYear(endDate,historicalYear+Math.max(0,endYear-startYear));try{const u=new URL('https://archive-api.open-meteo.com/v1/archive');u.searchParams.set('latitude',lat);u.searchParams.set('longitude',lon);u.searchParams.set('timezone','auto');u.searchParams.set('start_date',start);u.searchParams.set('end_date',end);u.searchParams.set('daily','weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum');const r=await fetch(u,{signal:AbortSignal.timeout(9000)});if(!r.ok)return null;const d=await r.json(),days=(d.daily?.time||[]).map((date,i)=>{const mapped=String(date).replace(/^\d{4}/,String(tripYear));return {date:mapped,weather_code:d.daily.weather_code?.[i],max:d.daily.temperature_2m_max?.[i],min:d.daily.temperature_2m_min?.[i],rain_probability:Number(d.daily.precipitation_sum?.[i]||0)>0?50:10,precipitation:d.daily.precipitation_sum?.[i],historical:true,historical_year:historicalYear}});return {place:{name:place.name,address:place.address,location:place.location},timezone:d.timezone||'',days,historical:true,historical_year:historicalYear}}catch(e){console.error('[historical weather]',e.message);return null}}
async function tripWeatherOverview(tripId,ownerId,t){return Promise.all(tripWeatherCandidates(tripId,ownerId,t).map(async c=>{try{const places=await googlePlaceSearch(c.query,1);if(!places[0])return {label:c.label,query:c.query,weather:null,typical:null,clothing:[],clothing_source:'unavailable'};const [weather,typical]=await Promise.all([openMeteoForecast(places[0]),openMeteoHistoricalTypical(places[0],t.start_date,t.end_date)]);const tripDays=new Set((()=>{const out=[],a=new Date(`${t.start_date}T12:00:00Z`),b=new Date(`${t.end_date}T12:00:00Z`);if(Number.isNaN(a.getTime())||Number.isNaN(b.getTime()))return out;for(let d=new Date(a);d<=b;d.setUTCDate(d.getUTCDate()+1))out.push(d.toISOString().slice(0,10));return out})());const realDays=(weather?.days||[]).filter(x=>tripDays.has(x.date));const effective=realDays.length?{...weather,days:realDays}:typical;return {label:c.label,query:c.query,weather,typical,clothing:clothesForWeather(effective),clothing_source:realDays.length?'forecast':(typical?'historical':'unavailable')}}catch{return {label:c.label,query:c.query,weather:null,typical:null,clothing:[],clothing_source:'unavailable'}}}))}
