function base32Encode(buf){const a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';let bits=0,v=0,out='';for(const b of buf){v=(v<<8)|b;bits+=8;while(bits>=5){out+=a[(v>>>(bits-5))&31];bits-=5}}if(bits)out+=a[(v<<(5-bits))&31];return out}
function base32Decode(str){const a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';let bits=0,v=0,out=[];for(const c of String(str).replace(/=|\s/g,'').toUpperCase()){const n=a.indexOf(c);if(n<0)continue;v=(v<<5)|n;bits+=5;if(bits>=8){out.push((v>>>(bits-8))&255);bits-=8}}return Buffer.from(out)}
function totp(secret,step=Math.floor(Date.now()/30000)){const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(step));const h=crypto.createHmac('sha1',base32Decode(secret)).update(b).digest(),o=h[19]&15,n=((h[o]&127)<<24)|(h[o+1]<<16)|(h[o+2]<<8)|h[o+3];return String(n%1000000).padStart(6,'0')}
function verifyTotp(secret,code){return [-1,0,1].some(d=>totp(secret,Math.floor(Date.now()/30000)+d)===String(code||'').trim())}
function hashPassword(password,salt=crypto.randomBytes(16).toString('hex')){ const h=crypto.scryptSync(password,salt,64).toString('hex'); return `scrypt$${salt}$${h}`; }
function verifyPassword(password,stored){ try{const [,salt,h]=stored.split('$'); return crypto.timingSafeEqual(Buffer.from(hashPassword(password,salt).split('$')[2],'hex'),Buffer.from(h,'hex'));}catch{return false;} }
function normalizeEmail(s){return String(s||'').trim().toLowerCase();}
function validEmail(s){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);}
function bootstrapAdmin(){const e=normalizeEmail(process.env.ADMIN_EMAIL), p=process.env.ADMIN_PASSWORD, n=process.env.ADMIN_NAME||'Administrador'; if(!e||!p)return; if(p.length<10) throw new Error('ADMIN_PASSWORD deve ter ao menos 10 caracteres'); const found=db.prepare('SELECT id FROM users WHERE email=?').get(e); if(!found) db.prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')").run(n,e,hashPassword(p));}
