function cookies(req){return Object.fromEntries((req.headers.cookie||'').split(';').map(x=>x.trim().split('=')).filter(x=>x.length===2).map(([k,v])=>[k,decodeURIComponent(v)]));}
function currentUser(req){const t=cookies(req).session; if(!t)return null; const th=crypto.createHash('sha256').update(t).digest('hex'); const sessionUser=db.prepare('SELECT user_id FROM sessions WHERE token_hash=?').get(th); if(sessionUser){try{refreshBillingEntitlement(sessionUser.user_id)}catch(e){console.error('[billing-entitlement] Falha de sincronização não bloqueia a sessão:',e.message)}} const row=db.prepare("SELECT u.id,u.name,u.email,u.phone,u.role,u.plan,u.test_plan,u.test_plan_until,u.created_at,u.email_verified,s.expires_at,(SELECT status FROM billing_subscriptions b WHERE b.user_id=u.id ORDER BY b.id DESC LIMIT 1) billing_status,(SELECT billing_cycle FROM billing_subscriptions b WHERE b.user_id=u.id ORDER BY b.id DESC LIMIT 1) billing_cycle,(SELECT entitlement_until FROM billing_subscriptions b WHERE b.user_id=u.id AND b.entitlement_until IS NOT NULL ORDER BY b.id DESC LIMIT 1) entitlement_until FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?").get(th); if(!row)return null; if(row.expires_at<Date.now()){db.prepare('DELETE FROM sessions WHERE token_hash=?').run(th); return null;} row.commercial_plan=row.plan; const testActive=row.test_plan&&(!row.test_plan_until||Date.parse(row.test_plan_until)>Date.now()); if(testActive)row.plan=row.test_plan; else if(row.test_plan){try{db.prepare('UPDATE users SET test_plan=NULL,test_plan_until=NULL,test_plan_granted_by=NULL WHERE id=?').run(row.id)}catch{} row.test_plan=null;row.test_plan_until=null;} return row;}
function cleanupExpiredSecurityTokens(){const now=Date.now();db.prepare('DELETE FROM sessions WHERE expires_at<?').run(now);db.prepare('DELETE FROM password_resets WHERE expires_at<?').run(now);db.prepare('DELETE FROM email_verifications WHERE expires_at<?').run(now);db.prepare('DELETE FROM email_changes WHERE expires_at<?').run(now);db.prepare("DELETE FROM trip_collaborations WHERE status='pending' AND expires_at IS NOT NULL AND expires_at<?").run(now);}
