function createSession(uid){db.prepare('DELETE FROM sessions WHERE expires_at<?').run(Date.now());const token=crypto.randomBytes(32).toString('base64url'), th=crypto.createHash('sha256').update(token).digest('hex');db.prepare('INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)').run(th,uid,Date.now()+SESSION_DAYS*86400000);try{const extras=db.prepare('SELECT token_hash FROM sessions WHERE user_id=? ORDER BY created_at DESC LIMIT -1 OFFSET 10').all(uid);for(const x of extras)db.prepare('DELETE FROM sessions WHERE token_hash=?').run(x.token_hash)}catch(e){console.warn('[auth] Sessão criada; limpeza de sessões antigas falhou:',e.message)}return token;}
